    void relation(String value){switch(value){case "ownedOutp"->registration(patient,BusinessDates.today().minusDays(3),actor.id(),"REGISTERED");case "today"->registration(patient,BusinessDates.today(),null,"REGISTERED");case "outpAuthor"->jdbc.update("update outp_emr set doctor_id=? where id=?",actor.id(),emr);case "futureOwned"->registration(patient,BusinessDates.today().plusDays(2),actor.id(),"REGISTERED");case "ownedInp"->jdbc.update("update inp_admission set doctor_id=? where id=?",actor.id(),admission);case "nullInp"->jdbc.update("update inp_admission set doctor_id=null where id=?",admission);case "inpAuthorOnly"->jdbc.update("update inp_medical_record set doctor_id=? where id=?",actor.id(),record);case "nullOutp"->jdbc.update("update outp_registration set doctor_id=null where id=?",registration);case "cancelledOwned"->registration(patient,BusinessDates.today(),actor.id(),"CANCELLED");case "cancelledPayload"->{jdbc.update("update outp_registration set status='CANCELLED' where id=?",registration);relation("ownedInp");}case "none"->{}default->throw new AssertionError(value);}}
    String endpoint(){String p=ROOT+"?fieldCode="+enc(fieldCode);if(searchValue!=null&&!searchValue.isEmpty())p+="&value="+enc(searchValue);if(!source.isEmpty())p+="&emrType="+enc(source);if(from!=null)p+="&from="+from;if(to!=null)p+="&to="+to;return p;}
