    Reply read()throws Exception{return call("GET",endpoint(),null,actor.token());}
    Wanted expected(){var u=jdbc.queryForList("select enabled from sys_user where id=?",actor.id());var roles=jdbc.queryForList("select r.code from sys_user_role ur join sys_role r on r.id=ur.role_id where ur.user_id=?",String.class,actor.id());if(u.isEmpty()||!Boolean.TRUE.equals(u.getFirst().get("enabled"))||roles.stream().noneMatch(Set.of("ADMIN","QUALITY","DOCTOR_OUTP","NURSE")::contains))return new Wanted(403,1005,null);return new Wanted(200,0,wire(expectedHits(roles)));}
    boolean allowed(Long p,boolean inp,List<String> roles){if(roles.contains("ADMIN")||roles.contains("QUALITY")||inp&&roles.contains("NURSE"))return true;if(!roles.contains("DOCTOR_OUTP"))return false;return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from outp_registration g where g.patient_id=? and g.status<>'CANCELLED' and (g.visit_date=? or g.doctor_id=? or exists(select 1 from outp_emr w where w.registration_id=g.id and w.doctor_id=?))) or exists(select 1 from inp_admission a where a.patient_id=? and a.doctor_id=?)",Boolean.class,p,BusinessDates.today(),actor.id(),actor.id(),p,actor.id()));}
    Map<String,Object> expectedHits(List<String> roles){var out=new ArrayList<Map<String,Object>>();String type=source.trim().toUpperCase();if(!type.equals("INP"))collect(out,false,roles);if(!type.equals("OUTP"))collect(out,true,roles);out.sort(Comparator.comparing(m->((Timestamp)m.get("recordedAt")).toInstant(),Comparator.reverseOrder()));boolean truncated=out.size()>200;return Map.of("fieldCode",fieldCode.trim(),"items",truncated?out.subList(0,200):out,"total",Math.min(200,out.size()),"limit",200,"truncated",truncated);}
    void collect(List<Map<String,Object>> out,boolean inp,List<String> roles){String sql=inp?"select r.id emr_id,r.admission_id visit_id,a.admission_no visit_no,a.patient_id,p.name patient_name,d.name dept_name,r.title,r.template_id,t.name template_name,r.created_at recorded_at,(r.content_json::json)->>cast(? as text) field_value from inp_medical_record r join inp_admission a on a.id=r.admission_id join empi_patient p on p.id=a.patient_id left join sys_dept d on d.id=a.dept_id left join emr_template t on t.id=r.template_id where r.content_json is not null order by r.created_at desc":"select e.id emr_id,e.registration_id visit_id,g.reg_no visit_no,g.patient_id,p.name patient_name,d.name dept_name,e.chief_complaint title,e.template_id,t.name template_name,e.updated_at recorded_at,(e.content_json::json)->>cast(? as text) field_value from outp_emr e join outp_registration g on g.id=e.registration_id join empi_patient p on p.id=g.patient_id left join sys_dept d on d.id=g.dept_id left join emr_template t on t.id=e.template_id where e.content_json is not null order by e.updated_at desc";for(var r:jdbc.queryForList(sql,fieldCode.trim())){if(r.get("field_value")==null||!allowed(((Number)r.get("patient_id")).longValue(),inp,roles))continue;String val=(String)r.get("field_value");if(searchValue!=null&&!val.toLowerCase(Locale.ROOT).contains(searchValue.trim().toLowerCase(Locale.ROOT)))continue;var time=(Timestamp)r.get("recorded_at");if(from!=null&&time.before(Timestamp.valueOf(LocalDate.parse(from).atStartOfDay())))continue;if(to!=null&&!time.before(Timestamp.valueOf(LocalDate.parse(to).plusDays(1).atStartOfDay())))continue;var hit=new LinkedHashMap<String,Object>();hit.put("emrType",inp?"INP":"OUTP");String[] snake={"emr_id","visit_id","visit_no","patient_id","patient_name","dept_name","title","template_id","template_name","field_value","recorded_at"};String[] camel={"emrId","visitId","visitNo","patientId","patientName","deptName","title","templateId","templateName","fieldValue","recordedAt"};for(int i=0;i<snake.length;i++)hit.put(camel[i],r.get(snake[i]));out.add(hit);}}
    static Stream<Arguments> matrix(){return Stream.of("ADMIN","QUALITY","DOCTOR_OUTP","NURSE","TECHNICIAN","DOCTOR_OUTP+NURSE","DOCTOR_OUTP+TECHNICIAN","NURSE+TECHNICIAN","ADMIN+TECHNICIAN","QUALITY+TECHNICIAN").flatMap(r->Stream.of("none","ownedOutp","ownedInp").flatMap(rel->Stream.of("","OUTP","INP").map(src->Arguments.of(r,rel,src))));}
