    @ParameterizedTest @ValueSource(ints={0,1,199,200,201,230})void authorizationPrecedesEach201LimitAndVisibleTruncation(int count)throws Exception{source="INP";Long visibleAdmission=admission;jdbc.update("update inp_admission set doctor_id=? where id=?",actor.id(),visibleAdmission);jdbc.update("delete from outp_emr where id=?",emr);jdbc.update("delete from inp_medical_record where id=?",record);Long hiddenPatient=newPatient("hidden");Long hiddenAdmission=jdbc.queryForObject("insert into inp_admission(admission_no,patient_id,dept_id,ward_id,bed_id,doctor_id,status) values (?,?,?,?,?,?,'DISCHARGED') returning id",Long.class,tag+"H",hiddenPatient,dept,dept,bed,owner.id());jdbc.update("insert into inp_medical_record(admission_id,record_type,title,content,doctor_id,content_json,created_at) select ?,'PROGRESS',?,'hidden',?,?,timestamptz '2026-05-01 00:00Z'+i*interval '1 second' from generate_series(1,250)i",hiddenAdmission,tag,owner.id(),jsonValues(oldNonce));if(count>0)jdbc.update("insert into inp_medical_record(admission_id,record_type,title,content,doctor_id,content_json,created_at) select ?,'PROGRESS',?,'visible',?,?,timestamptz '2026-01-01 00:00Z'+i*interval '1 second' from generate_series(1,?)i",visibleAdmission,tag,actor.id(),jsonValues(oldNonce),count);try{check("limit-hidden250-visible"+count);}finally{jdbc.update("delete from inp_medical_record where admission_id=?",hiddenAdmission);jdbc.update("delete from inp_admission where id=?",hiddenAdmission);jdbc.update("delete from empi_patient where id=?",hiddenPatient);}}
