    @ParameterizedTest @ValueSource(strings={"anonymous","disabled","CASHIER","TECHNICIAN"})void entryJwtAndOriginalFourDutyGateRemain(String kind)throws Exception{String token=actor.token();int http=403,code=1005;if(kind.equals("anonymous")){token=null;http=401;code=1000;}else if(kind.equals("disabled")){jdbc.update("update sys_user set enabled=false where id=?",actor.id());http=401;code=1000;}else roles(actor,kind);Wanted w=new Wanted(http,code,null);var before=facts();var old=audit();verify("entry-"+kind,call("GET",endpoint(),null,token),w,before,old,null,false);}
    void mutation(String method,String path,Object body,Staff who)throws Exception{Reply reply=call(method,path,body,who.token());var e=new LinkedHashMap<String,Object>();e.put("method",method);e.put("path",path);e.put("actor",who.name());e.put("body",body);e.put("response",reply.body());e.put("http",reply.http());maintenance.add(e);response(reply,200,0);if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())entityManager.flush();}
    void publicRoles(String...values)throws Exception{mutation("PUT","/api/system/users/"+actor.id(),Map.of("username",actor.name(),"realName",actor.name(),"deptId",dept,"roleCodes",List.of(values)),admin);}
    void publishNew()throws Exception{mutation("PUT","/api/outpatient/doctor/"+registration+"/emr",Map.of("emr",Map.of("chiefComplaint",newNonce,"presentIllness","公开结构化发布"),"diagnoses",List.of(),"templateId",template,"fields",Map.of(tag+"_text",newNonce)),owner);mutation("POST","/api/inpatient/admissions/"+admission+"/records",Map.of("recordType","PROGRESS","title",tag+"新标题","content",newNonce,"templateId",template,"fields",Map.of(tag+"_text",newNonce)),owner);}
    void change(String kind)throws Exception{switch(kind){case "attendingLoss"->mutation("PUT","/api/inpatient/admissions/"+admission+"/attending-doctor",Map.of("doctorId",owner.id()),admin);case "attendingGain"->mutation("PUT","/api/inpatient/admissions/"+admission+"/attending-doctor",Map.of("doctorId",actor.id()),admin);case "adminLoss"->publicRoles("DOCTOR_OUTP");case "nurseOnly"->publicRoles("NURSE");case "dutyLoss"->publicRoles("TECHNICIAN");case "disabled"->mutation("PUT","/api/system/users/"+actor.id()+"/enabled?enabled=false",null,admin);default->throw new AssertionError(kind);}publishNew();}
