    void window(String label,String kind,boolean after,boolean rollback)throws Exception{Wanted wanted=expected();var old=audit();Gap gap=new Gap(after,true);var pool=Executors.newSingleThreadExecutor();Future<Reply> pending=pool.submit(()->{Gap.TRACE.set(gap);try{return read();}finally{Gap.TRACE.remove();SecurityContextHolder.clearContext();}});try{gap.await();if(rollback){var tx=new TransactionTemplate(transactions);tx.setTimeout(20);var original=facts();tx.executeWithoutResult(status->{try{change(kind);entityManager.flush();entityManager.clear();status.setRollbackOnly();}catch(Exception e){throw new RuntimeException(e);}});assertEquals(original,facts());}else{change(kind);if(!after)wanted=expected();}var before=facts();gap.release();verify(label,pending.get(25,TimeUnit.SECONDS),wanted,before,old,gap,rollback);}finally{gap.release();pool.shutdown();assertTrue(pool.awaitTermination(25,TimeUnit.SECONDS));}}
    @Test void bothSourcesAreFetchedInExactlyOnePayloadStatement()throws Exception{roles(actor,"ADMIN");var gap=new Gap(false,false);Gap.TRACE.set(gap);try{check("one-statement");assertEquals(1,gap.executions.get(),gap.statements.toString());}finally{Gap.TRACE.remove();}}
    @ParameterizedTest @ValueSource(strings={"missingAdmin","missingQuality","existingNoDuty"})void noTrustedInternalEmployeeFallback(String kind){if(!kind.equals("null")){String name=kind.startsWith("missing")?tag+"missing":actor.name();if(kind.equals("existingNoDuty"))roles(actor,"TECHNICIAN");SecurityContextHolder.getContext().setAuthentication(new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(name,null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority(kind.endsWith("Quality")?"ROLE_QUALITY":"ROLE_ADMIN"))));}var before=facts();try{assertThrows(org.springframework.security.access.AccessDeniedException.class,()->controller.fieldSearch(fieldCode,null,null,null,null));}finally{SecurityContextHolder.clearContext();}assertEquals(before,facts());}
    Reply check(String label)throws Exception{return check(label,expected());}Reply check(String label,Wanted wanted)throws Exception{var before=facts();var old=audit();Reply reply=read();verify(label,reply,wanted,before,old,null,false);return reply;}
    void verify(String label,Reply reply,Wanted wanted,Map<String,List<String>> before,List<Map<String,Object>> old,Gap gap,boolean rollback){var after=facts();evidence(label,reply,wanted,before,after,old,gap,rollback);assertAll(()->{response(reply,wanted.http(),wanted.code());if(wanted.code()==0){assertEquals(OUTER_KEYS,keys(reply.body().path("data")));assertEquals(wanted.data(),reply.body().path("data"));for(var h:reply.body().path("data").path("items"))assertEquals(HIT_KEYS,keys(h));}},()->assertEquals(before,after,"GET cannot change any monitored business/auth/config column"),()->{var events=new ArrayList<Map<String,Object>>();if(!rollback)events.addAll(maintenance);var e=new LinkedHashMap<String,Object>();e.put("method","GET");e.put("path",wanted.http()==401||wanted.http()==403?ROOT:reply.path());e.put("actor",wanted.http()==401?null:actor.name());e.put("http",wanted.http());events.add(e);audited(old,events);});System.out.println("V153 CASE "+label+" actual="+reply.http()+"/"+reply.code()+" expected="+wanted.http()+"/"+wanted.code());}
    Set<String> keys(JsonNode node){var keys=new HashSet<String>();node.fieldNames().forEachRemaining(keys::add);return keys;}
    Reply call(String method,String path,Object body,String token)throws Exception{
        SecurityContextHolder.clearContext();try{MockHttpServletRequestBuilder req=method.equals("POST")?post(path):method.equals("PUT")?put(path):get(path);if(method.equals("GET")&&path.contains("?")){req=get(path.substring(0,path.indexOf('?')));for(String p:path.substring(path.indexOf('?')+1).split("&")){String[] kv=p.split("=",2);req.queryParam(URLDecoder.decode(kv[0],StandardCharsets.UTF_8),URLDecoder.decode(kv.length==2?kv[1]:"",StandardCharsets.UTF_8));}}if(body!=null)req.contentType("application/json").content(mapper.writeValueAsBytes(body));if(token!=null)req.header("Authorization","Bearer "+token);var actual=mvc.perform(req).andReturn();var r=actual.getResponse();String qs=actual.getRequest().getQueryString();String observed=actual.getRequest().getRequestURI()+(qs==null||qs.isBlank()?"":"?"+qs);return new Reply(r.getStatus(),mapper.readTree(r.getContentAsString(StandardCharsets.UTF_8)),observed);}finally{SecurityContextHolder.clearContext();}
    }
    JsonNode wire(Object value){try{return mapper.readTree(mapper.writeValueAsBytes(value));}catch(Exception e){throw new AssertionError(e);}}
    void response(Reply r,int status,int code){assertEquals(Set.of("code","message","data"),keys(r.body()));assertEquals(status,r.http(),r.body().toString());assertEquals(code,r.code(),r.body().toString());if(code!=0)assertTrue(r.body().path("data").isNull());}
    Map<String,List<String>> facts(){var out=new LinkedHashMap<String,List<String>>();for(String t:TABLES)out.put(t,jdbc.queryForList("select to_jsonb(t)::text from "+t+" t order by id",String.class));out.put("config",jdbc.queryForList("select to_jsonb(t)::text from sys_config t order by cfg_key",String.class));out.put("roles",jdbc.queryForList("select to_jsonb(t)::text from sys_user_role t order by user_id,role_id",String.class));out.put("users",jdbc.queryForList("select ((to_jsonb(t)-'password')||jsonb_build_object('passwordDigest',md5(t.password)))::text from sys_user t order by id",String.class));return out;}
    List<Map<String,Object>> audit(){return jdbc.queryForList("select id,username,method,path,http_status,client_ip,created_at::text as created_at from sys_audit_log order by id");}
    void audited(List<Map<String,Object>> old,List<Map<String,Object>> events){var all=audit();assertTrue(all.containsAll(old));var added=new ArrayList<>(all);added.removeAll(old);assertEquals(events.size(),added.size(),added.toString());for(var e:events){String path=(String)e.get("path");var matches=added.stream().filter(a->Objects.equals(a.get("method"),e.get("method"))&&Objects.equals(a.get("path"),path)&&Objects.equals(a.get("username"),e.get("actor"))&&((Number)a.get("http_status")).intValue()==((Number)e.get("http")).intValue()).toList();assertFalse(matches.isEmpty(),e.toString());var a=matches.getFirst();assertEquals(Set.of("id","username","method","path","http_status","client_ip","created_at"),a.keySet());assertEquals("127.0.0.1",a.get("client_ip"));added.remove(a);}assertTrue(added.isEmpty());}
    void evidence(String label,Reply reply,Wanted wanted,Map<String,List<String>> before,Map<String,List<String>> after,List<Map<String,Object>> old,Gap gap,boolean rollback){String folder=System.getProperty("hip.v153.evidenceDir");if(folder==null)return;try{Path dir=Path.of(folder);Files.createDirectories(dir);var out=new LinkedHashMap<String,Object>();out.put("label",label);out.put("tag",tag);out.put("http",reply.http());out.put("path",reply.path());out.put("response",reply.body());out.put("expectedHttp",wanted.http());out.put("expectedCode",wanted.code());out.put("expectedData",wanted.data());out.put("before",before);out.put("after",after);out.put("oldAudit",old);out.put("currentAudit",audit());out.put("publicChanges",maintenance);out.put("changesRolledBack",rollback);out.put("oldNonce",oldNonce);out.put("newNonce",newNonce);if(gap!=null)out.put("jdbcBoundary",gap.proof());Files.writeString(dir.resolve(tag+"-"+(++artifact)+".json"),mapper.writeValueAsString(out),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}catch(Exception e){throw new AssertionError(e);}}
    static final class Gap{static final ThreadLocal<Gap> TRACE=new ThreadLocal<>();final boolean after,pause;final CountDownLatch reached=new CountDownLatch(1),resume=new CountDownLatch(1);final AtomicInteger executions=new AtomicInteger(),pauses=new AtomicInteger();final List<Map<String,Object>> statements=new ArrayList<>();Gap(boolean after,boolean pause){this.after=after;this.pause=pause;}void observe(String sql,Map<Integer,Object> params,boolean done,int fetch){String n=sql.replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);if(!n.contains("field_value")||!(n.contains("from outp_emr e")||n.contains("from inp_medical_record r"))||n.contains("for update"))return;if(!done)executions.incrementAndGet();var e=new LinkedHashMap<String,Object>();e.put("sql",sql);e.put("parameters",new TreeMap<>(params));e.put("position",done?"AFTER":"BEFORE");e.put("thread",Thread.currentThread().getName());e.put("time",Instant.now().toString());e.put("fetchSize",fetch);statements.add(e);if(pause&&done==after&&pauses.compareAndSet(0,1)){assertEquals(0,fetch);reached.countDown();try{assertTrue(resume.await(25,TimeUnit.SECONDS));}catch(InterruptedException x){Thread.currentThread().interrupt();throw new AssertionError(x);}}}void await()throws Exception{assertTrue(reached.await(20,TimeUnit.SECONDS),"Real field-search execute boundary missing");assertEquals(1,pauses.get());}void release(){resume.countDown();}Map<String,Object> proof(){return Map.of("kind","transparent actual JDBC executeQuery","postgresLockWaitClaim",false,"after",after,"pauses",pauses.get(),"payloadExecutions",executions.get(),"statements",statements);}}
    @TestConfiguration(proxyBeanMethods=false) static class JdbcConfiguration{@Bean @Primary JdbcTemplate fieldSearchBoundaryJdbcTemplate(DataSource actual){return new JdbcTemplate(new BoundaryDataSource(actual));}}
    static final class BoundaryDataSource extends DelegatingDataSource{
        BoundaryDataSource(DataSource actual){super(new TransactionAwareDataSourceProxy(actual));}
        @Override public Connection getConnection()throws SQLException{return connection(super.getConnection());}
        @Override public Connection getConnection(String u,String p)throws SQLException{return connection(super.getConnection(u,p));}
        Connection connection(Connection actual){return(Connection)Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class<?>[]{Connection.class},(p,m,a)->{Object v=invoke(actual,m,a);return m.getName().equals("prepareStatement")&&a!=null&&a[0] instanceof String sql&&v instanceof PreparedStatement ps?statement(ps,sql):v;});}
        PreparedStatement statement(PreparedStatement actual,String sql){var params=new TreeMap<Integer,Object>();return(PreparedStatement)Proxy.newProxyInstance(PreparedStatement.class.getClassLoader(),new Class<?>[]{PreparedStatement.class},(p,m,a)->{if(m.getName().startsWith("set")&&a!=null&&a.length>=2&&a[0] instanceof Integer i)params.put(i,m.getName().equals("setNull")?null:a[1]);if(m.getName().equals("clearParameters"))params.clear();Gap g=Gap.TRACE.get();boolean q=m.getName().equals("executeQuery")&&(a==null||a.length==0);if(g!=null&&q)g.observe(sql,params,false,actual.getFetchSize());Object v=invoke(actual,m,a);if(g!=null&&q)g.observe(sql,params,true,actual.getFetchSize());return v;});}
        static Object invoke(Object target,Method method,Object[] args)throws Throwable{try{return method.invoke(target,args);}catch(InvocationTargetException e){throw e.getCause();}}
    }
    @AfterEach void cleanup(){Gap.TRACE.remove();SecurityContextHolder.clearContext();for(Long reg:registrations){jdbc.update("delete from emr_version where emr_type='OUTP' and emr_id in(select id from outp_emr where registration_id=?)",reg);jdbc.update("delete from outp_diagnosis_version where registration_id=?",reg);jdbc.update("delete from outp_diagnosis where registration_id=?",reg);jdbc.update("delete from outp_emr where registration_id=?",reg);jdbc.update("delete from outp_registration where id=?",reg);}jdbc.update("delete from emr_version where emr_type='INP' and emr_id in(select id from inp_medical_record where admission_id=?)",admission);jdbc.update("delete from inp_medical_record where admission_id=?",admission);jdbc.update("delete from inp_admission where id=?",admission);jdbc.update("delete from inp_bed where id=?",bed);for(Long id:schedules)jdbc.update("delete from outp_schedule where id=?",id);jdbc.update("delete from emr_template_field where template_id=?",template);jdbc.update("delete from emr_template_grant where template_id=?",template);jdbc.update("delete from emr_template where id=?",template);jdbc.update("delete from empi_patient where name in (?,?)",tag+"patient",tag+"other");for(Staff p:people){jdbc.update("delete from sys_user_role where user_id=?",p.id());jdbc.update("delete from sys_user where id=?",p.id());}jdbc.update("delete from sys_dept where id=?",dept);}
